<?php
declare(strict_types=1);
namespace App\Modules\CommercialRental\Services;
use App\Modules\CommercialRental\Models\CommercialRentalCategory;use RuntimeException;
final class CommercialRentalCategoryService{private CommercialRentalCategory $m;public function __construct(){$this->m=new CommercialRentalCategory();}public function all(int $t):array{return$this->m->all($t);}public function find(int$t,int$id):?array{return$this->m->find($t,$id);}public function count(int$t):int{return$this->m->count($t);}public function create(int$t,array$i,int$u):int{$d=$this->v($i);$d['slug']=$this->unique($t,$d['slug']);return$this->m->create($t,$d,$u);}public function update(int$t,int$id,array$i,int$u):void{$d=$this->v($i);$d['slug']=$this->unique($t,$d['slug'],$id);$this->m->update($t,$id,$d,$u);}public function delete(int$t,int$id,int$u):void{$this->m->delete($t,$id,$u);}private function v(array$i):array{$n=trim((string)($i['name']??''));if(!$n)throw new RuntimeException('Category name is required.');$s=strtolower(trim((string)($i['slug']??'')));$s=$s?:$this->slugify($n);$st=(string)($i['status']??'Active');if(!in_array($st,['Active','Inactive'],true))throw new RuntimeException('Invalid status.');return['name'=>$n,'slug'=>$s,'description'=>trim((string)($i['description']??''))?:null,'status'=>$st];}private function unique(int$t,string$b,?int$ignore=null):string{$c=$b;$n=2;while($this->m->exists($t,$c,$ignore))$c=$b.'-'.$n++;return$c;}private function slugify(string$v):string{$v=strtolower(trim($v));$v=preg_replace('/[^a-z0-9]+/','-',$v)??'';return trim($v,'-');}}
